void RestfulInventoryCtrl::summary(const HttpRequestPtr &req,std::function<void(const HttpResponsePtr &)> &&callback)
{
    try {
        auto inventoryScope=erp::business::documentScope("inventory","i",req);
        auto recordScope=erp::business::documentScope("stock_records","s",req);
        auto rows=getDbClient()->execSqlSync("SELECT (SELECT COUNT(*) FROM products) AS product_count,(SELECT COUNT(*) FROM inventory i WHERE "+inventoryScope+") AS inventory_count,(SELECT COALESCE(SUM(quantity),0) FROM inventory i WHERE "+inventoryScope+") AS total_quantity,(SELECT COUNT(*) FROM inventory i WHERE ("+inventoryScope+") AND i.quantity<=i.min_quantity) AS low_stock,(SELECT COUNT(*) FROM stock_records s WHERE "+recordScope+") AS record_count");
        Json::Value stats;for(const auto *name:{"product_count","inventory_count","total_quantity","low_stock","record_count"})stats[name]=Json::Int64(rows[0][name].as<int64_t>());
        callback(erp::ApiResponse::ok(stats));
    } catch(const std::exception &e) { LOG_ERROR<<e.what();callback(erp::ApiResponse::error(erp::ErrorCode::INTERNAL_ERROR,"库存统计加载失败")); }
}


