void RestfulInventoryCtrl::updateSafetyStock(
    const HttpRequestPtr &req,
    std::function<void(const HttpResponsePtr &)> &&callback,
    Inventory::PrimaryKeyType &&id)
{
    auto json = req->getJsonObject();
    if (!json || !json->isMember("min_quantity"))
    {
        auto resp = HttpResponse::newHttpJsonResponse(
            []() { Json::Value r; r["error"] = "缺少 min_quantity 参数"; return r; }());
        resp->setStatusCode(k400BadRequest);
        callback(resp);
        return;
    }
    auto dbClientPtr = getDbClient();
    try
    {
        if(!(*json)["min_quantity"].isIntegral() || (*json)["min_quantity"].asInt64()<0 || (*json)["min_quantity"].asInt64()>2147483647) {
            callback(erp::ApiResponse::error(erp::ErrorCode::BAD_REQUEST,"安全库存必须为非负整数"));return;
        }
        int minQty = (*json)["min_quantity"].asInt();
        auto result = dbClientPtr->execSqlSync(
            "UPDATE inventory SET min_quantity = ? WHERE id = ?", minQty, id);
        if (result.affectedRows() == 0 && dbClientPtr->execSqlSync("SELECT id FROM inventory WHERE id=?",id).empty())
        {
            auto resp = HttpResponse::newHttpJsonResponse(
                []() { Json::Value r; r["error"] = "库存记录不存在"; return r; }());
            resp->setStatusCode(k404NotFound);
            callback(resp);
            return;
        }
        Json::Value ret;
        ret["id"] = (Json::UInt64)id;
        ret["min_quantity"] = minQty;
        callback(HttpResponse::newHttpJsonResponse(ret));
    }
    catch (const std::exception &e)
    {
        LOG_ERROR << e.what();
        Json::Value ret;
        ret["error"] = std::string("更新安全库存失败: ") + e.what();
        auto resp = HttpResponse::newHttpJsonResponse(ret);
        resp->setStatusCode(k500InternalServerError);
        callback(resp);
    }
}
